export const meta = {
  name: 'app-dev-without-prd',
  description: 'App dev without PRD, one command: every question in one stop at the start → the source app audited (store ∥ APK files with layouts and code data ∥ every screen walked) → every gap decided from the evidence and recorded (never asked) → PRD.md (every line sourced, answered or decided; the app\'s own theme and files), gated by source-app.mjs check → /app-factory:build-app: contract (gaps decided, nothing asked) → development → ads → device tests → senior QA → final audit',
  whenToUse: 'Rebuild the user\'s own existing app (an update of it) — all of its functionality, its own theme, colours, icon, images, animations and sounds — when there is no PRD and no Figma design. Run it in an empty project folder (an .apk/.apks/.xapk of the app may be in it) with the app\'s link as args: a Google Play or App Store link, or its website — {"app":"<link>"} or just the link. Optional: "apk":"<path>", "name":"<the new app\'s name>", "note":"<anything the build must follow>". It stops ONCE, at the start, to ask every question (the source app, the APK set, where the walk runs and where if it fails, the new name) and returns "nextStep": do exactly what it says — ask them all with AskUserQuestion, wait for the answers, relaunch with them. After that nothing is asked: every gap is decided from the evidence and recorded in DECISIONS.md, and once PRD.md passes it starts /app-factory:build-app, which asks nothing either.',
  phases: [
    { title: 'Source', detail: 'the link resolved; the APK set checked (complete, signed, one app); the only questions of the run: the source app, the APK set, where the walk runs and where if it fails, the new name' },
    { title: 'Audit', detail: 'in parallel: store + web listing → store.md; APK files → static.md (layouts, code data) + the app\'s own files → source-app/assets/; every screen walked on the chosen device → walk.md + screenshots' },
    { title: 'Decide', detail: 'every behaviour PRD.md needs that no evidence shows gets the option closest to the evidence and the answers, recorded in source-app/answers.md and DECISIONS.md — nothing is asked' },
    { title: 'Report', detail: 'PRD.md (every line sourced, every seen screen/feature/dependency/file covered) + the source app\'s own theme in source-app/theme.json, until source-app.mjs check passes' },
  ],
}

const obj = (required, properties) => ({ type: 'object', required, properties })
const str = { type: 'string' }
const int = { type: 'integer' }
const bool = { type: 'boolean' }
const strs = { type: 'array', items: str }
const QUESTIONS = { type: 'array', items: obj(['id', 'header', 'question', 'options', 'why'], { id: str, header: str, question: str, options: { type: 'array', items: obj(['label', 'description'], { label: str, description: str }) }, why: str }) }

// args: an object, a JSON string, or the bare link.
const ARGS = typeof args === 'string'
  ? (() => { try { return JSON.parse(args) } catch { const t = args.trim(); return /^https?:\/\//.test(t) ? { app: t } : t ? { note: t } : {} } })()
  : (args || {})
// The user's answers (the relaunch carries them). Every question is asked in ONE stop at the start, before the audit,
// and waited for: link, apk, walk, walkfallback, name (user, 2026-11-04). After it nothing is asked: a gap the evidence
// leaves gets the option closest to the evidence and the answers, recorded as [decided: gap-<n>] (answers.md, DECISIONS.md).
const ANSWERS = Array.isArray(ARGS.answers) ? ARGS.answers : []
const label = (a) => String(a.answer).replace(/ \(Recommended\)$/, '') // the first option's label carries " (Recommended)"
const ANS = Object.fromEntries(ANSWERS.map((a) => [a.id, label(a)]))
const NO_WALK = 'Go on without the walk'
const walkPick = ANS.walk || ''
const SKIP_WALK = ANS.apk === NO_WALK || walkPick === NO_WALK
// a device answer → its mode: "My phone" / "Play on emulator" / "Plugin emulator" (an own answer is matched by its words)
const modeOf = (t) => (!t || t === NO_WALK ? 'none' : /phone/i.test(t) ? 'phone' : /play/i.test(t) ? 'play' : 'emulator')
const WALK_ON = SKIP_WALK ? 'none' : modeOf(walkPick)
const askAll = (qs, what) => `Ask the user ALL ${qs.length} question(s) in "questions" (${qs.map((q) => q.id).join(', ')}) — ${what} — with the AskUserQuestion tool, up to 4 questions per call, in the order given, as many calls as it takes. Each: header = its header, question = its question, options = its options as given (label and description; the first one ends in "(Recommended)"); never add, drop or reword an option, never answer one yourself, never start a timer: wait for the answers however long they take. A reply with a key value: store it with \`printf '%s' '<the value>' | node "${ROOT}/scripts/pipeline.mjs" secret set <NAME>\` in the project directory and use the answer "provided" — never repeat the value. Then run the workflow app-factory:app-dev-without-prd again in this same chat with these args, with one entry per question added to the end of "answers" — {"id":"<id>","question":"<question>","answer":"<the option's label or the user's own text>","by":"user"}: ${JSON.stringify({ ...ARGS, answers: ANSWERS })}`
const ask = (qs, what) => {
  const open = (qs || []).filter((q) => q && !(q.id in ANS)).map((q) => ({ ...q, header: String(q.header).slice(0, 12) }))
  if (!open.length) return null
  log(`${open.length} question(s) for the user (${what}) — the run waits for the answers`)
  return { stage: 'questions', questions: open, nextStep: askAll(open, what) }
}
// ponytail: a workflow script cannot ask where its plugin lives — configure.mjs / self-configure.mjs write these defaults per machine.
const ROOT = ARGS.root || '/Users/mach/testing/app-factory'
const ANDROID_SDK = ARGS.androidSdk || '/Users/mach/Library/Android/sdk'
const JAVA_HOME = ARGS.javaHome || '/opt/homebrew/opt/openjdk@17'
const PIPE = `${ROOT}/scripts/pipeline.mjs`
const CHECK = `node "${ROOT}/scripts/source-app.mjs"`
const ADB = `"${ANDROID_SDK}/platform-tools/adb"`
const AAPT = `"$(ls -d "${ANDROID_SDK}"/build-tools/*/ | sort -V | tail -1)aapt2"`
const APKANALYZER = `JAVA_HOME="${JAVA_HOME}" "${ANDROID_SDK}/cmdline-tools/latest/bin/apkanalyzer"`
let P = `node "${PIPE}"`

const where = (dir) => `Project directory: ${dir} — run every command there.${ARGS.note ? ` The user's note for this run: ${JSON.stringify(String(ARGS.note))}.` : ''}
This run audits an EXISTING app (the "source app") so that /app-factory:build-app can rebuild all of it. The source app is the USER'S OWN app — this is a rebuild and update of it, never a copy of someone else's: its theme (colours, fonts), its icon, images, Lottie animations and sounds are reused as they are, never replaced by look-alikes, and no question asks for a "new" colour, theme, font or icon style. The user has no PRD and no Figma design: the evidence you collect is the only spec, so it must be exact. Report only what a source shows — a store page, a web page, the APK's files, or the app on the emulator — and give each fact its source. What no source shows is "NOT OBSERVED" — it is then decided (the option closest to the evidence and the answers) and recorded, never a silent guess. Write no vague words: "etc", "and more", "various", "similar to", "as needed", "appropriate", "probably", "maybe", "TBD", "…" — state the exact text, number or behaviour.
The user is watching .pipeline/PROGRESS.md live: report as you go with \`${P} log source "<what you are doing or what just happened>"\` — when you start, before each long step and after each result. Never ask the user: the Source step's questions, asked once at the start, are the only ones of this run. Anything else unclear is decided — the option closest to the evidence and the answers — and recorded as your task says.${ANSWERS.length ? ` The user's answers so far (also in source-app/answers.md): ${JSON.stringify(ANSWERS.map((a) => ({ id: a.id, question: a.question, answer: a.answer })))}.` : ''} Never start a background, detached or headless process (\`&\`, \`nohup\`, \`claude -p\`); run every command in the foreground.
Files: the evidence goes ONLY into source-app/ (the files your task names); raw dumps, decompiled output and downloads go into ${dir}.source/ (outside the project). Never copy an image, icon, font, text file, key or ID value of the source app into the project except the screenshots your task names. A key, token or ID you see (AIza…, sk_…, an AdMob or Firebase id): record "<service> key present" — never its value.
This computer is the user's: never run sudo, pkill, killall, kill by name, reboot, or delete a device; the plugin's guard refuses them. Read only what you need: grep -n first, then the lines you need; batch independent reads and commands in one turn.`
let WHERE = where('.')

// ───────────────────────────── Source: the link and the APK ─────────────────────────────
phase('Source')
const src = await agent(
  `${WHERE}
Setup — find what can be audited. In order, stop at the first failure (ok=false, stop = the reason, in one sentence the user can act on):
1. \`pwd\` → projectDir. Work an earlier run left here is continued, never started over: \`${CHECK} status .\` prints {sourceApp, store, static, walk (the ids each evidence file holds; 0 = missing, or a walk that reached no screen), prd, prdProblems, staticMissing, contract, app, dartFiles} → return it as "have" exactly, then:
   - sourceApp false and (prd true, or any *PRD*.md exists) → stop: "This folder already has a PRD — use /app-factory:build-app."
   - sourceApp false and app true → stop: "This folder already has an app and no audit of a source app — use an empty folder (the source app's APK may be in it)."
   - otherwise continue with step 2: the evidence files with ids are kept as they are, PRD.md, CONTRACT.md and the app's code are never deleted or rewritten here — the run decides from "have" what to re-audit and what to add.
2. \`mkdir -p "$(pwd).source" source-app/store source-app/screens\` → scratch = "$(pwd).source". \`${P} init PRD.md\` (the PRD this run writes), then \`${P} log source "auditing ${ARGS.app ? ARGS.app.replace(/"/g, '') : 'the APK in the folder'}"\`.${ANSWERS.length ? ` Add the answers above to source-app/answers.md ("# Answers" when the file is new): per answer, "## <id> · <question>" then "Answer: <answer>" — the user's words as given; PRD.md cites them as [user]. An answer with the same id already in the file is replaced; every other earlier answer and the "## Decided without asking" section stay as they are — the earlier run's answers are still the user's.` : ''} Earlier answers to questions this version never asks — a new or different colour, theme, font, corner radius, elevation or icon style, or where images come from because the source's files "may not be copied" — are moved, as written, under "## Superseded" at the end of answers.md with the line "Why: the source app is the user's own — its theme, fonts, icon, images, animations and sounds are kept (plugin 0.54.0)"; nothing cites them.
3. The link: ${ARGS.app ? `"${ARGS.app}"` : 'none given'}. Google Play (play.google.com/store/apps/details?id=<package>) → androidPackage. App Store (apps.apple.com/…/id<digits>) → iosId = the digits; then \`curl -s "https://itunes.apple.com/lookup?id=<iosId>&country=us"\` → its trackName and sellerName, and find its Android version: WebSearch \`"<trackName>" "<sellerName>" site:play.google.com\` → a Play link whose developer is the same sellerName → androidPackage. Any other URL → website (fetch it and take a Play or App Store link it gives). ${ANS.link ? `The user answered which app it is: ${JSON.stringify(ANS.link)} — use it.` : 'More than one Play app could be it, or none and there is no APK → question "link" (header "Source app"): one option per candidate (title — developer — package), the closest match first.'}
4. The APK set: ${ARGS.apk ? `"${ARGS.apk}"` : '`find . -maxdepth 2 \\( -iname "*.apk" -o -iname "*.apks" -o -iname "*.xapk" -o -iname "*.apkm" \\) -not -path "./build/*"`'}. A bundle (.apks, .xapk, .apkm — a zip of APKs): \`unzip -o -q <file> "*.apk" -d <scratch>/apk\`, and every APK in it is one install set. Files of different apps (check each with \`${AAPT} dump badging <apk> | head -1\`) → stop: "The folder has APKs of more than one app (<packages>) — keep only the one to rebuild." The base APK is base.apk, or the one whose badging line has no split=. Its package must equal androidPackage when the link gave one → else stop: "The APK is <package>, the link is <androidPackage> — they are different apps." No androidPackage yet → take it from the APK.
   No APK in the folder, but static.md or PRD.md's Sources names the one an earlier run audited (its file or folder name, package, shasum) → look for it beside the project: \`find "$(dirname "$(pwd)")" -maxdepth 3 \\( -iname "*.apk" -o -iname "*.apks" -o -iname "*.xapk" -o -iname "*.apkm" -o -name AndroidManifest.xml \\) -not -path "*/build/*" -not -path "*/android/*" -not -path "*/ios/*"\`; one of that package (badging, or the manifest's package=) → use it as below, and say where it was found.
   No APK file, but an unzipped APK in the folder (\`find . -maxdepth 2 -name AndroidManifest.xml -not -path "./android/*" -not -path "./build/*" -not -path "./ios/*"\` with classes.dex beside it) → \`(cd "<that folder>" && zip -q -r -X "<scratch>/apk/unzipped-base.apk" .)\` is the base for the APK-files audit; unzipped = true. It cannot be installed: unzipping drops the v2/v3 signature block (\`ls "<folder>/META-INF"\` shows whether a v1 .RSA/.SF/.EC is left).
   splitsMissing = the base's manifest requires splits (\`${APKANALYZER} manifest print <base> | grep -A1 com.android.vending.splits.required\` → value true) and the set has no split APK (no split= among the badging lines). pairip = \`${APKANALYZER} manifest print <base> | grep -c com.pairip\` > 0 (Play's licence check: a copy not installed by Play may stop at its licence screen). installable = an APK set is here, not unzipped, and not splitsMissing.
5. A connected phone with the app: when androidPackage is known — \`${P} devices real --sdk "${ANDROID_SDK}"\` → for each Android phone \`${ADB} -s <serial> shell pm path <androidPackage>\`; listed → phone = that serial, phoneModel = its model. That is all you do on the phone here.${ANS.apk === 'Pull from my phone' ? ` The user chose "Pull from my phone": \`${ADB} -s <phone> pull <each path> <scratch>/apk/\` (base and every split), apkFrom = "phone"; these are the set (installable when signed and complete).` : ''}
6. Never download an APK from a website or mirror (an unverified build of someone else's app).
7. .gitignore: append each of these lines that is missing (create the file if needed): *.apk, *.apks, *.xapk, *.apkm — the APK is evidence, not part of the new app.
8. Questions — return in "questions" each of these whose id is not in the user's answers above and whose subject source-app/answers.md does not already answer outside "## Superseded" (an earlier run's answer to the app name, Firebase, purchases or keys is used, not asked again; "apk" and "walk" are asked again only when what they decide is still missing now) (id; header of at most 12 characters; question ending in "?"; 2 to 4 options, each a label of at most 5 words and a one-line description of what happens, the recommended one first with " (Recommended)" at the end of its label; why = what it decides):
   - "apk" (header "APK set"), only when not installable: the question says exactly what is missing (no APK; only an unzipped APK with no signature; a base APK without its <n> split APKs, as res/xml/splits0.xml or the manifest shows). Options in this order, each only when it applies: "Pull from my phone" (phone has the app: base and splits copied read only; nothing on the phone changes); "I'll add the APK set" (put the .apks/.xapk/.apkm, or base.apk with every split_config.*.apk, in the folder, then answer); "${NO_WALK}" (no walk: screens come from the APK's layouts and the store screenshots, and every behaviour no file shows is asked before PRD.md).${ANS.apk === "I'll add the APK set" ? ' The user answered "I\'ll add the APK set": no APK file and no unzipped APK in the folder → stop: "The folder still has no APK of the app: <what is missing>." An unzipped or incomplete set is used for its files (static.md and the reused files); the walk then runs where "walk" or "walkfallback" says.' : ''}
   - "walk" (header "Walk on"), when walk.md has no walked screen (have.walk 0), the walk can run somewhere and the user did not choose "${NO_WALK}": options, each only when it applies — "Plugin emulator" (installable: the set is installed on the plugin's own emulator af-standard; with pairip it may stop at Play's licence screen), "Play on emulator" (androidPackage known: the emulator, a Google Play image, opens the app's Play page; the user signs in to a Google account in the emulator window and taps Install; the walk waits up to 30 minutes; the account stays on that emulator), "My phone" (phone has the app: the walk uses the app as installed on <phoneModel> — taps every control, switches airplane and dark mode and puts them back, never buys, signs in, sends or deletes; records it creates stay in the app; the first launch cannot be seen). Recommended first: "Plugin emulator" when installable and not pairip; else "My phone" when there is a phone; else "Play on emulator". Only one option applies → no question; that one is used.
   - "name" (header "App name")${ARGS.name ? ' — skip: the name was given' : ''}: it is the user's own app, so the first option (recommended) is "Keep <the source app's name>" (when PRD.md exists: "Keep <the name in its App section>"), then 2 new names you propose for a rebrand. Answered "Keep …", the App section's name is that name.
   - "firebase" (header "Firebase") — skip when a google-services.json is already in the folder: "The rebuilt app's ads, Remote Config, push and analytics need its own Firebase files — the ads code starts AdMob only after Firebase, so without them no ad shows. Will you add them?" Options: "I'll add them now (Recommended)" — "Create a free Firebase project (console.firebase.google.com), add the Android app with package <androidPackage> and the iOS app, put google-services.json and GoogleService-Info.plist in this folder, then answer"; "Without Firebase for now" — "No ads, Remote Config, push or analytics until they are added".
   - "purchases" (header "Purchases"): "The Premium purchase uses RevenueCat. Which key should the build test purchases with?" Options: "Test Store key (Recommended)" — "RevenueCat dashboard → Apps and providers → Test configuration → create a Test Store; then in this folder run node \"${PIPE}\" secret set REVENUECAT_TEST_API_KEY and paste it: real test purchases, no store setup"; "Real store keys" — "secret set REVENUECAT_GOOGLE_API_KEY and REVENUECAT_APPLE_API_KEY the same way"; "Without purchases for now" — "The paywall is built; Subscribe says subscriptions aren't available yet".
   - "keys" (header "API keys"): "Which keys and hosts of your own services (the AI model, your own APIs) should the rebuilt app use?" Options: "I'll type them (Recommended)" — "Under Other: each service's base URL, model or endpoint, how to call it, and its key — the key is stored outside the project and never shown again"; "None" — "Features that need a service show 'isn't available yet' until it is added". An answer with keys → write one line per key, "<SERVICE> API key: <the key>", into a file in the scratch folder, run \`${P} secret import <that file>\` (each key is stored as <SERVICE>_API_KEY, never shown), delete the file, and check \`${P} secret names\` lists every one, and write the hosts, models and instructions (never a key) into source-app/answers.md.
   - "link" as step 3 says.
Return ok, stop, have, projectDir, scratch, link, androidPackage, iosId, website, apks (absolute paths; the base first — the zipped unzipped folder counts), apkFrom, unzipped, splitsMissing, pairip, installable, phone, phoneModel and questions.`,
  { label: 'source', phase: 'Source', schema: obj(['ok', 'have', 'projectDir', 'scratch', 'apks', 'apkFrom'], { ok: bool, stop: str, have: obj(['store', 'static', 'walk', 'prd', 'prdProblems', 'staticMissing', 'contract', 'app', 'dartFiles'], { store: int, static: int, walk: int, prd: bool, prdProblems: { type: ['integer', 'null'] }, staticMissing: strs, contract: bool, app: bool, dartFiles: int }), projectDir: str, scratch: str, link: str, androidPackage: str, iosId: str, website: str, apks: strs, apkFrom: { type: 'string', enum: ['folder', 'phone', 'none'] }, unzipped: bool, splitsMissing: bool, pairip: bool, installable: bool, phone: str, phoneModel: str, questions: QUESTIONS }), effort: 'low' },
)
if (!src || !src.ok) {
  log(`stopped: ${(src && src.stop) || 'the setup step returned no result'}`)
  return { aborted: true, stop: src && src.stop }
}
const HAVE = src.have
// build-app asks nothing for this command: its contract gaps are decided and recorded like the PRD's (one stop, at the start)
const NOTE = `,"decideAll":true${ARGS.note ? `,"note":${JSON.stringify(String(ARGS.note))}` : ''}`
const buildApp = (args, done) => `Tell the user in one line: ${done}. Then, in this same chat, run the workflow app-factory:build-app (the /app-factory:build-app command) with args ${args} and follow its nextStep as always.`
// An earlier run got this far: re-audit what it left and continue from it — never start over. PRD.md that passes the
// current check, with every part of static.md this version writes, goes on to build-app, which re-audits CONTRACT.md
// against it and continues from the code; otherwise PRD.md is re-audited here first (missing evidence added, every gap
// asked, the check's problems fixed), CONTRACT.md and the code kept.
const NEED_STATIC = HAVE.static > 0 && (HAVE.staticMissing || []).length > 0 && src.apks.length > 0
if (HAVE.prd && HAVE.prdProblems === 0 && !NEED_STATIC) {
  log(HAVE.contract
    ? `continuing: PRD.md passes the check and CONTRACT.md is here — build-app re-audits the contract against PRD.md, then the build continues from the ${HAVE.dartFiles} .dart file(s) in lib/`
    : 'continuing: PRD.md is here and passes the check — the audit is not run again')
  return { done: true, resumed: HAVE.contract ? 'build' : 'prd', have: HAVE, nextStep: buildApp(`{"noFigma":true${NOTE}}`, HAVE.contract
    ? `PRD.md passes the audit check and CONTRACT.md is here (${HAVE.dartFiles} .dart files in lib/): the contract is re-audited against PRD.md and the build continues from the code already here`
    : 'the audit and PRD.md from the earlier run are done and pass the check, so the contract is written from them') }
}
if (HAVE.prd) log(`re-auditing PRD.md: ${HAVE.prdProblems} check problem(s)${NEED_STATIC ? `; static.md lacks ${HAVE.staticMissing.join(', ')} (added from the APK)` : ''}${HAVE.walk ? '' : '; no walked screen'}${HAVE.contract ? ` — CONTRACT.md and the ${HAVE.dartFiles} .dart file(s) are kept; build-app re-audits the contract afterwards and continues from the code` : ''}`)
// Questions before the audit: nothing is audited on a guess about the APK set, the device or the name.
// Where the walk can run, and the second place if the first reaches no screen — asked now, with the rest, so a failed walk
// never stops the run later. Recommended: the walk's own order (emulator when installable and no Play licence check, else
// the phone, else Play on the emulator); for the fallback, the next place in [phone, Play, emulator] after that one.
const CAN = { emulator: Boolean(src.installable) || (src.questions || []).some((q) => q.id === 'apk'), phone: Boolean(src.phone), play: Boolean(src.androidPackage) }
const LABEL = { emulator: 'Plugin emulator', phone: 'My phone', play: 'Play on emulator' }
const DESC = { emulator: 'install the APK set on the plugin\'s emulator af-standard (when the set is complete and signed)', phone: `the app as installed on your phone${src.phoneModel ? ` (${src.phoneModel})` : ''}: settings saved and put back, records the walk creates stay`, play: 'you sign in to Google Play in the emulator window and tap Install; the walk waits up to 30 minutes' }
const firstWalk = src.installable && !src.pairip ? 'emulator' : src.phone ? 'phone' : src.androidPackage ? 'play' : 'emulator'
const fallbacks = ['phone', 'play', 'emulator'].filter((m) => CAN[m] && m !== firstWalk)
const fallbackQ = !SKIP_WALK && !HAVE.walk && Object.values(CAN).some(Boolean) ? [{
  id: 'walkfallback', header: 'If walk fails',
  question: 'If the walk reaches no screen on the device chosen for it (install refused, Play\'s licence screen, a crash at start), where should it run instead?',
  options: [...fallbacks.map((m) => ({ label: LABEL[m], description: DESC[m] })), { label: NO_WALK, description: 'no walk: screens come from the APK\'s layouts and the store screenshots; what no file shows is decided from the evidence and recorded' }].slice(0, 4).map((o, i) => (i ? o : { ...o, label: `${o.label} (Recommended)` })),
  why: 'nothing is asked after the start, so the second place is chosen now',
}] : []
const startQs = ask([...(src.questions || []).filter((q) => !(q.id === 'walk' && (SKIP_WALK || HAVE.walk > 0))), ...fallbackQ], 'every question of this run, asked once before the audit: the source app, its APK set, where the walk runs and where if it fails, the new app\'s name — nothing is asked after this')
if (startQs) return startQs
const DIR = src.projectDir.trim()
const SCRATCH = src.scratch.trim()
P = `PIPELINE_DIR="${DIR}/.pipeline" node "${PIPE}"`
WHERE = where(DIR)
const APK = src.apks.length > 0
const BASE = APK ? src.apks[0] : ''
const INSTALL = src.apks.length > 1 ? `${ADB} -s <serial> install-multiple -r ${src.apks.map((a) => `"${a}"`).join(' ')}` : `${ADB} -s <serial> install -r "${BASE}"`
// The walk's device: the user's answer; when only one place could run it (no question was asked), that one.
const WALK_MODE = SKIP_WALK ? 'none' : walkPick ? WALK_ON : src.installable && !src.pairip ? 'emulator' : src.phone ? 'phone' : src.androidPackage ? 'play' : src.installable ? 'emulator' : 'none'
const canWalkOn = (m) => (m === 'emulator' ? Boolean(src.installable) : m === 'phone' ? Boolean(src.phone) : m === 'play' ? Boolean(src.androidPackage) : false)
